const $=id=>document.getElementById(id),csrf=()=>{const m=document.cookie.match(/(?:^|; )studio_csrf=([^;]+)/);return m?decodeURIComponent(m[1]):''};function note(text,error=false){const e=$('global-alert');e.textContent=text;e.hidden=!text;e.className='alert '+(error?'error':'success')}async function api(path,method='GET',body){const h={};if(body!==undefined)h['Content-Type']='application/json';if(!['GET','HEAD'].includes(method))h['X-CSRF-Token']=csrf();const r=await fetch(path,{method,headers:h,credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body)});let d={};try{d=await r.json()}catch{}if(!r.ok){const e=new Error(d.error||d.detail||'Request failed.');e.status=r.status;throw e}return d}function mark(id,ready,text){const e=$(id);e.textContent=text|| (ready?'Ready':'Not configured');e.className='status-chip '+(ready?'ready':'off')}
document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const i=$(b.dataset.toggle);i.type=i.type==='password'?'text':'password';b.textContent=i.type==='text'?'Hide':'Show'});
async function load(){try{const a=await api('/api/auth/status');if(a.owner_exists&&!a.authenticated){location.replace('/signin');return}const s=await api('/api/auth/setup/status');$('origin').textContent=s.authorized_origin;$('google-callback').textContent=s.callbacks.google;$('github-callback').textContent=s.callbacks.github;mark('owner-status',s.owner_exists,s.owner_exists?'Owner account enabled':'Optional');$('owner-summary').textContent=s.owner_exists?(s.owner_email||'Signed in locally. Your studio data remains in the existing local database.'):'No account is enabled. Local Ollama and current local features work without signing in.';$('change-password').hidden=!s.authenticated||!s.owner_exists;$('signin-link').hidden=s.owner_exists;$('no-password').hidden=!(s.authenticated&&s.owner_exists);mark('google-status',s.google.ready);$('google-remove').hidden=!s.google.configured;$('google-link').hidden=!(s.authenticated&&s.google.ready);mark('github-status',s.github.connected,s.github.connected?'Connected as '+s.github.login:s.github.configured?'Ready to connect':'Not configured');$('github-remove').hidden=!s.github.configured;$('github-account').textContent=s.github.connected?'Connected account: '+s.github.login:'Repository access is disconnected; App setup is '+(s.github.configured?'saved and ready to reconnect.':'not configured.');mark('email-status',s.email.ready,s.email.ready?'Reset email ready':'Not configured');$('email-remove').hidden=!s.email.configured;const q=new URLSearchParams(location.search);if(q.get('google')==='linked')note('Google account linked.');if(q.get('google')==='denied')note('Google authorization was denied.',true)}catch(e){if(e.status===401){location.replace('/signin');return}note(e.message,true)}}
load();
$('signout').onclick=async()=>{try{await api('/api/auth/logout','POST',{});location.replace('/signin')}catch(e){note(e.message,true)}};
$('google-form').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('[type=submit]');b.disabled=true;b.textContent='Validating…';try{await api('/api/auth/setup/google','POST',{client_id:$('google-id').value.trim(),client_secret:$('google-secret').value});$('google-secret').value='';$('google-id').value='';note('Google OAuth credentials saved in the OS credential manager. Verify the exact callback in Google Cloud Console.');await load()}catch(x){note(x.message,true)}finally{b.disabled=false;b.textContent='Validate and save'}};
$('google-remove').onclick=async()=>{if(!confirm('Remove Google OAuth configuration from this computer?'))return;try{await api('/api/auth/setup/google','DELETE');note('Google OAuth configuration removed.');await load()}catch(e){note(e.message,true)}};
$('google-link').onclick=async()=>{try{const d=await api('/api/auth/google/link','POST',{});location.assign(d.url)}catch(e){note(e.message,true)}};
$('github-form').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('[type=submit]');b.disabled=true;b.textContent='Validating…';try{await api('/api/auth/setup/github','POST',{client_id:$('github-id').value.trim(),client_secret:$('github-secret').value});$('github-secret').value='';$('github-id').value='';note('GitHub App configuration saved in the OS credential manager. Confirm the displayed callback and read-only permissions in GitHub.');await load()}catch(x){note(x.message,true)}finally{b.disabled=false;b.textContent='Validate and save'}};
$('github-remove').onclick=async()=>{if(!confirm('Disconnect GitHub and remove the saved App configuration?'))return;try{await api('/api/auth/setup/github','DELETE');note('GitHub connection and App configuration removed.');await load()}catch(e){note(e.message,true)}};
$('email-form').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('[type=submit]');b.disabled=true;b.textContent='Testing SMTP…';try{await api('/api/auth/setup/email','POST',{host:$('smtp-host').value.trim(),port:$('smtp-port').value,security:$('smtp-security').value,username:$('smtp-username').value.trim(),password:$('smtp-password').value,from_email:$('smtp-from').value.trim()});$('smtp-password').value='';note('SMTP connection verified; password recovery is enabled.');await load()}catch(x){note(x.message,true)}finally{b.disabled=false;b.textContent='Test connection and save'}};
$('email-remove').onclick=async()=>{if(!confirm('Disable email password recovery and remove the saved SMTP configuration?'))return;try{await api('/api/auth/setup/email','DELETE');note('Email password recovery disabled.');await load()}catch(e){note(e.message,true)}};
$('change-password').onsubmit=async e=>{e.preventDefault();try{await api('/api/auth/password/change','POST',{current_password:$('current-password').value,new_password:$('new-password').value});$('current-password').value='';$('new-password').value='';note('Password updated. Other active sessions have been signed out.')}catch(x){note(x.message,true)}};
